import React from 'react';
import './ResumePreview.css';

/**
 * Component for rendering a preview of the uploaded resume.
 */
const ResumePreview = ({ analysisData }) => {
  const extractedText = analysisData?.extractedText || analysisData?.extracted_text || analysisData?.text || '';
  const fileName = analysisData?.originalName || analysisData?.original_name || analysisData?.filename || 'Uploaded resume';
  const status = analysisData?.status || 'ready';

  return (
    <div className="resume-preview">
      <h2>Resume Preview</h2>
      {analysisData ? (
        <div>
          <p><strong>File:</strong> {fileName}</p>
          <p><strong>Status:</strong> {status}</p>
          {extractedText ? (
            <pre className="resume-preview__text">{extractedText}</pre>
          ) : (
            <p>No extracted text is available yet.</p>
          )}
        </div>
      ) : (
        <p>The uploaded document preview will appear here after implementation.</p>
      )}
    </div>
  );
};

export default ResumePreview;
